const fs = require('fs/promises');
const path = require('path');
const crypto = require('crypto');
const env = require('../config/env');

/**
 * All filesystem access for submissions lives here. Routes and controllers never build paths.
 *  - File names are generated by the server (random UUID); the user's file name is never used.
 *  - Paths are stored relative to the uploads directory and re-checked on every read, so a
 *    tampered database value such as "../../etc/passwd" cannot escape the upload root.
 *  - Uploaded code is only ever read as text. It is never executed.
 */
function resolveSafe(relativePath) {
  const root = path.resolve(env.uploadDir);
  const full = path.resolve(root, relativePath);
  if (full !== root && !full.startsWith(root + path.sep)) throw new Error('Unsafe file path');
  return full;
}

async function save(buffer, { assignmentId, studentId, extension }) {
  const storedFilename = `${studentId}-${crypto.randomUUID()}${extension}`;
  const relativePath = path.join(String(assignmentId), storedFilename);
  const full = resolveSafe(relativePath);
  await fs.mkdir(path.dirname(full), { recursive: true });
  await fs.writeFile(full, buffer, { flag: 'wx', mode: 0o640 });
  return { storedFilename, relativePath };
}

async function readText(relativePath) {
  return fs.readFile(resolveSafe(relativePath), 'utf8');
}

async function remove(relativePath) {
  try { await fs.unlink(resolveSafe(relativePath)); } catch { /* already gone */ }
}

module.exports = { save, readText, remove, resolveSafe };
